ALTER TABLE templates ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE variable_types(id integer PRIMARY KEY CHECK(id BETWEEN 110001 AND 119999),code text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO variable_types(id,code,name) VALUES(110001,'string','ข้อความ'),(110002,'object','กลุ่มข้อมูล'),(110003,'array','รายการ');
CREATE FUNCTION protect_type_code() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.code IS DISTINCT FROM OLD.code THEN RAISE EXCEPTION 'Master meaning is immutable' USING ERRCODE='55000'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER stable_type BEFORE UPDATE ON variable_types FOR EACH ROW EXECUTE FUNCTION protect_type_code();
CREATE TABLE template_current(template_id text PRIMARY KEY REFERENCES templates(id),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE formats(id uuid PRIMARY KEY,template_id text NOT NULL REFERENCES template_current(template_id) ON DELETE CASCADE,key text NOT NULL,position integer NOT NULL CHECK(position>=0),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(template_id,key),UNIQUE(id,template_id));
CREATE TABLE variable_schemas(id uuid PRIMARY KEY,template_id text NOT NULL REFERENCES template_current(template_id) ON DELETE CASCADE,format_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(format_id,template_id) REFERENCES formats(id,template_id) ON DELETE CASCADE,UNIQUE NULLS NOT DISTINCT(template_id,format_id));
CREATE TABLE variables(id uuid PRIMARY KEY,schema_id uuid NOT NULL REFERENCES variable_schemas(id) ON DELETE CASCADE,parent_id uuid,key text NOT NULL, type_id integer NOT NULL REFERENCES variable_types(id),position integer NOT NULL CHECK(position>=0),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,schema_id),FOREIGN KEY(parent_id,schema_id) REFERENCES variables(id,schema_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,UNIQUE NULLS NOT DISTINCT(schema_id,parent_id,key));
CREATE TABLE template_snapshots(version_id uuid PRIMARY KEY REFERENCES template_versions(id),payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE format_versions(id uuid PRIMARY KEY,template_version_id uuid NOT NULL REFERENCES template_snapshots(version_id),source_format_id uuid,key text NOT NULL,position integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,template_version_id),UNIQUE(template_version_id,key));
CREATE TABLE variable_schema_versions(id uuid PRIMARY KEY,template_version_id uuid NOT NULL REFERENCES template_snapshots(version_id),source_schema_id uuid,format_version_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(format_version_id,template_version_id) REFERENCES format_versions(id,template_version_id),UNIQUE NULLS NOT DISTINCT(template_version_id,format_version_id));
CREATE TABLE variable_versions(id uuid PRIMARY KEY,schema_version_id uuid NOT NULL REFERENCES variable_schema_versions(id),source_variable_id uuid,parent_version_id uuid,key text NOT NULL,type_id integer NOT NULL REFERENCES variable_types(id),position integer NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,schema_version_id),FOREIGN KEY(parent_version_id,schema_version_id) REFERENCES variable_versions(id,schema_version_id) DEFERRABLE INITIALLY DEFERRED,UNIQUE NULLS NOT DISTINCT(schema_version_id,parent_version_id,key));
CREATE TABLE publication_receipts(template_id text NOT NULL REFERENCES templates(id),request_id text NOT NULL CHECK(length(request_id) BETWEEN 1 AND 200),version_id uuid NOT NULL REFERENCES template_versions(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(template_id,request_id));
CREATE TRIGGER immutable_snapshot BEFORE UPDATE OR DELETE ON template_snapshots FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();
CREATE TRIGGER immutable_format_version BEFORE UPDATE OR DELETE ON format_versions FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();
CREATE TRIGGER immutable_schema_version BEFORE UPDATE OR DELETE ON variable_schema_versions FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();
CREATE TRIGGER immutable_variable_version BEFORE UPDATE OR DELETE ON variable_versions FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();
CREATE TRIGGER immutable_receipt BEFORE UPDATE OR DELETE ON publication_receipts FOR EACH ROW EXECUTE FUNCTION reject_version_mutation();
